initial_code:
def how_many_times(string: str, substring: str) -> int:
    if not string or not substring:
        return 0

    count = 0
    start = 0

    while True:
        pos = string.find(substring, start)
        if pos == -1:
            break
        count += 1
        start = pos + 1  # Move by 1 to count overlapping occurrences

    return count

