initial_code:
def correct_bracketing(brackets: str) -> bool:
    balance = 0
    for bracket in brackets:
        if bracket == '<':
            balance += 1
        elif bracket == '>':
            balance -= 1
            # If we have more closing than opening brackets at any point, it's invalid
            if balance < 0:
                return False
    # Valid bracketing requires equal number of opening and closing brackets
    return balance == 0

