initial_code:
def anti_shuffle(s):
    words = s.split()
    result = []

    for word in words:
        # Sort characters in the word in ascending order based on ASCII value
        sorted_word = ''.join(sorted(word))
        result.append(sorted_word)

    # Join the words back with spaces
    return ' '.join(result)

