initial_code:
def encrypt(s):
    result = []
    for char in s:
        if 'a' <= char <= 'z':
            # Shift by 4 positions (2 * 2)
            shifted = ord(char) + 4
            # Wrap around if necessary
            if shifted > ord('z'):
                shifted = ord('a') + (shifted - ord('z') - 1)
            result.append(chr(shifted))
        elif 'A' <= char <= 'Z':
            # Shift by 4 positions (2 * 2)
            shifted = ord(char) + 4
            # Wrap around if necessary
            if shifted > ord('Z'):
                shifted = ord('A') + (shifted - ord('Z') - 1)
            result.append(chr(shifted))
        else:
            # Keep non-alphabetic characters unchanged
            result.append(char)
    return ''.join(result)

