initial_code:
def encode(message):
    vowels = 'aeiouAEIOU'
    vowel_map = {
        'a': 'c', 'e': 'g', 'i': 'k', 'o': 'q', 'u': 'w',
        'A': 'C', 'E': 'G', 'I': 'K', 'O': 'Q', 'U': 'W'
    }

    result = []

    for char in message:
        if char in vowels:
            # Replace vowel with the letter 2 places ahead
            result.append(vowel_map[char])
        else:
            # Swap case
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())

    return ''.join(result)

