def count_nums(arr):
    def sum_of_digits(num):
        total = 0
        for digit_char in str(abs(num)):
            total += int(digit_char)
        # Handle negative numbers - the first digit is negative
        if num < 0:
            total -= 2 * int(str(abs(num))[0])
        return total

    count = 0
    for num in arr:
        if sum_of_digits(num) > 0:
            count += 1
    return count

