import re
from typing import List

def select_words(s: str, n: int) -> List[str]:
    if not s:
        return []

    vowels = set("aeiouAEIOU")
    result = []

    # Split string into words
    words = s.split()

    for word in words:
        # Count consonants in the word
        consonant_count = 0
        for char in word:
            if char.isalpha() and char not in vowels:
                consonant_count += 1

        # If the word has exactly n consonants, add it to result
        if consonant_count == n:
            result.append(word)

    return result

