def get_closest_vowel(word):
    vowels = "aeiouAEIOU"

    # Check from right to left, skipping the last character (ending doesn't count)
    for i in range(len(word) - 2, 0, -1):
        current_char = word[i]
        if current_char in vowels:
            # Check if the character to the left and right are consonants
            left_char = word[i - 1]
            right_char = word[i + 1]

            if left_char not in vowels and right_char not in vowels:
                return current_char

    return ""

