initial_code:
def match_parens(lst):
    s1, s2 = lst[0], lst[1]

    # Check if we can make a balanced string by concatenating s1 + s2
    def is_balanced(s):
        balance = 0
        for c in s:
            if c == '(':
                balance += 1
            else:  # c == ')'
                balance -= 1
                if balance < 0:
                    return False
        return balance == 0

    # Check both possible orders
    if is_balanced(s1 + s2) or is_balanced(s2 + s1):
        return 'Yes'
    else:
        return 'No'

