initial_code:
def valid_date(date):
    # Check if the date string is not empty
    if not date:
        return False

    # Check if the format is mm-dd-yyyy (using hyphens only)
    if '-' not in date or date.count('-') != 2:
        return False

    # Split the date string by hyphens
    parts = date.split('-')
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    # Check if all parts are digits
    if not (month_str.isdigit() and day_str.isdigit() and year_str.isdigit()):
        return False

    # Convert to integers
    try:
        month = int(month_str)
        day = int(day_str)
        year = int(year_str)
    except ValueError:
        return False

    # Check month range (1-12)
    if month < 1 or month > 12:
        return False

    # Check day range based on month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    elif month == 2:
        if day < 1 or day > 29:
            return False

    return True

