initial_code:
def fix_spaces(text):
    result = []
    i = 0
    while i < len(text):
        if text[i] == ' ':
            space_count = 0
            # Count consecutive spaces
            j = i
            while j < len(text) and text[j] == ' ':
                space_count += 1
                j += 1

            # Replace with underscore if 1 or 2 spaces, with - if 3 or more
            if space_count <= 2:
                result.append('_')
            else:
                result.append('-')

            i = j  # Move past all consecutive spaces
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)

