def file_name_check(file_name):
    # Check if there's exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    # Split the file name into name and extension
    name_part, extension_part = file_name.split('.')

    # Check if name part is empty
    if not name_part:
        return 'No'

    # Check if name part starts with a letter
    if not (name_part[0].isalpha()):
        return 'No'

    # Check if extension is one of the allowed types
    if extension_part not in ['txt', 'exe', 'dll']:
        return 'No'

    # Check if there are more than three digits in the entire file name
    digit_count = 0
    for char in file_name:
        if char.isdigit():
            digit_count += 1

    if digit_count > 3:
        return 'No'

    return 'Yes'

