initial_code:
def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise."""

    if n < 2:
        return y

    if n == 2:
        return x

    if n % 2 == 0:
        return y

    # Check odd divisors up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return y
        i += 2

    return x

