    """You are given 2 words. You need to return True if the second word or any of its rotations is a substring in the first word"""
    # Create a string that contains all rotations of b by concatenating b with itself
    doubled_b = b + b

    # Check if any rotation of b (which is a substring of doubled_b) is in a
    for i in range(len(b)):
        rotation = doubled_b[i:i + len(b)]
        if rotation in a:
            return True

    return False

