initial_code:
def int_to_mini_roman(number):
    """Given a positive integer, obtain its roman numeral equivalent as a string, and return it in lowercase."""
    # Define the values and corresponding Roman numerals in descending order
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    numerals = ['m', 'cm', 'd', 'cd', 'c', 'xc', 'l', 'xl', 'x', 'ix', 'v', 'iv', 'i']

    result = []

    for i in range(len(values)):
        count = int(number // values[i])
        if count:
            result.append(numerals[i] * count)
            number -= values[i] * count

    return ''.join(result)

