from typing import List

def find_max(words: List[str]) -> str:
    def count_unique_chars(word: str) -> int:
        return len(set(word))

    # Find the maximum number of unique characters
    max_unique = 0
    result = ""

    for word in words:
        unique_count = count_unique_chars(word)
        if unique_count > max_unique:
            max_unique = unique_count
            result = word

    return result

