initial_code:
def generate_integers(a, b):
    """Given two positive integers a and b, return the even digits between a and b, in ascending order."""
    # Ensure we work with the range in ascending order
    start, end = min(a, b), max(a, b)

    # Collect even digits (0, 2, 4, 6, 8) that appear in numbers from start to end
    result = []

    for num in range(start, end + 1):
        # Convert number to string to iterate through digits
        for digit_char in str(num):
            digit = int(digit_char)
            if digit % 2 == 0:
                result.append(digit)

    # Remove duplicates and sort (though they should already be in order)
    return sorted(list(set(result)))

